def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids only (immediate reaction)
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids)
        second_prev_bid = sorted_b[-2]

    # Supply-based urgency: lower supply => higher chance others fight harder
    # Map supply in [15,25] to a multiplier in [1.15, 0.85]
    if supply <= MIN_SUPPLY:
        supply_mult = 1.15
    elif supply >= MAX_SUPPLY:
        supply_mult = 0.85
    else:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        supply_mult = 1.15 - 0.30 * t

    # Our urgency based on HP and consecutive no-water days
    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.35
    elif hp <= 4.0:
        urgency += 0.20
    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days == 1:
        urgency += 0.10

    # If opponents previously bid aggressively, slightly overbid to secure water
    # Target bid uses: max(half-salary, second-highest+delta, salary*threshold) scaled by supply.
    base = DAILY_SALARY * 0.55
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Cindy/Bob-like behavior: bid closer to their level but not fully.
        target = max(base, second_prev_bid + 2.0, highest_prev_bid * 0.72)
    else:
        # Moderate pressure: bid above base and somewhat above second-highest.
        target = max(base, second_prev_bid + 1.5, highest_prev_bid * 0.55)

    target *= supply_mult
    target *= (1.0 + urgency)

    # Safety rails: avoid extreme bids beyond what budget can support
    # Also avoid low bids when our HP is threatened.
    min_bid = 0.0
    if hp <= 2.0:
        min_bid = DAILY_SALARY * 0.85
    elif hp <= 4.0:
        min_bid = DAILY_SALARY * 0.65
    elif no_water_days >= 2:
        min_bid = DAILY_SALARY * 0.60
    else:
        min_bid = DAILY_SALARY * 0.45

    bid = max(min_bid, target)

    # Ensure bid does not exceed budget
    if budget <= 0:
        return 0.0

    if bid > budget:
        bid = budget

    # If budget is very low, still bid enough to avoid immediate death
    if budget < DAILY_SALARY * 0.5:
        # keep some reserve
        bid = min(bid, budget * 0.9)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_prev = []
    needy_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                needy_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= DAILY_SALARY * 0.8:
                    strong_prev.append(bid)

    if not alive_opponents:
        return min(budget, 18.0)

    competitors = len(alive_opponents) + 1
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < competitors * 0.75
    very_scarce = expected_units < competitors * 0.55

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        bid = max(81.0, highest_prev + 3.0)
    elif hp <= 4 or no_water >= 1:
        if very_scarce:
            bid = max(68.0, highest_prev + 2.0)
        else:
            bid = max(54.0, avg_prev + 2.0)
    else:
        if very_scarce:
            bid = max(60.0, highest_prev + 1.5)
        elif scarcity:
            bid = max(42.0, avg_prev + 1.5)
        else:
            bid = 24.0

    if needy_count >= 2:
        bid += 8.0
    elif needy_count == 1:
        bid += 4.0

    if len(strong_prev) >= 2 and hp > 4 and no_water == 0 and not very_scarce:
        bid = min(bid, 28.0)

    if day >= 8:
        bid += 6.0

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if hp <= 3 or no_water >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid a minimal amount to secure water
    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid, adjusted by HP
    # Default bid (when HP is good, no yesterday bids, or no high bids from opponents)
    bid_value = DAILY_SALARY * 0.5

    # Prioritize survival based on HP and no_water_days
    if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
        # Critical state: Must get water. Bid very high.
        bid_value = DAILY_SALARY * 0.95
        if yesterday_bids:
            bid_value = max(bid_value, max(yesterday_bids) * 1.05) # Try to beat the highest
    elif my_status['hp'] <= 7:
        # Moderate HP: Need water soon. Be aggressive.
        bid_value = DAILY_SALARY * 0.8
        if yesterday_bids:
            # Aim to beat the highest previous bid, but with a slightly lower multiplier than critical
            bid_value = max(bid_value, max(yesterday_bids) * 1.02)
    else: # my_status['hp'] > 7 (Good HP)
        # Can afford to be strategic.
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

            # If opponents are bidding very high (e.g., Bob's typical bids),
            # and my HP is good, concede this round to save budget.
            if highest_prev_bid > DAILY_SALARY * 0.9: # e.g., > 135
                bid_value = DAILY_SALARY * 0.3 # Bid low to save, hope others drain budget
            else:
                # Otherwise, try to win by bidding slightly above average
                bid_value = max(DAILY_SALARY * 0.6, avg_prev_bid * 1.05)
        # If no yesterday bids and good HP, bid_value remains DAILY_SALARY * 0.5 as initialized.

    # Ensure bid does not exceed current budget
    final_bid = min(my_status['budget'], bid_value)

    # Ensure bid is at least 0.0 (handled by min() and max() if budget > 0, but explicit for safety)
    if final_bid < 0:
        final_bid = 0.0

    return float(final_bid)
